add_filter( 'woocommerce_package_rates', 'perfectpixel_ship_to_specific_states_only', 10, 2 );

function perfectpixel_ship_to_specific_states_only( $rates, $package ) {
	$country = strtoupper( '{{ship_states_country}}' );
	$allowed = array_filter( array_map( 'trim', explode( ',', strtoupper( '{{ship_states_codes}}' ) ) ) );
	$dest    = $package['destination'] ?? array();

	if ( $allowed && strtoupper( $dest['country'] ?? '' ) === $country && ! in_array( strtoupper( $dest['state'] ?? '' ), $allowed, true ) ) {
		return array();
	}
	return $rates;
}
